%[text] # Motor Drive Unit - Simulation Case
%[text] ## Driving motor
%[text] Test that the motor can drive the axle. Stress-test check points
%[text] 1. Simulation must work regardless of the rotational direction.
%[text] 2. A sudden change in the rotational direction must be handled reasonably.   \
MotorDriveUnit_Basic_params
target_subsystem = "MotorDriveUnit_Basic_refsub";

stop_time = "400";

model_name = "HarnessModel_MotorDriveUnit";
load_system(model_name)
%[text] Test conditions
LoadInputs_MotorDriveUnit_Drive
%[text] Initial conditions
initial.LoadInertia_AngularSpeed = simscape.Value(0, "rpm");
initial.MotorDriveUnit_RotorAngularSpeed = simscape.Value(0, "rpm");
initial.AmbientTemperature = simscape.Value(273.15 + 20, "K");
%[text] 
sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, model_name + "/Motor Drive Unit", ReferencedSubsystem = "MotorDriveUnit_Basic_refsub");
sim_in = setBlockParameter(sim_in, model_name + "/Inputs", ReferencedSubsystem = "Inputs_MotorDriveUnit_LookupTable_refsub");
sim_in = setModelParameter(sim_in, StopTime = stop_time);
applyToModel(sim_in)
%[text] Run simulation.
sim_out = sim(sim_in);
%[text] Visually inspect the result.
sim_data = extractTimetable(sim_out.logsout);

% Signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];

for idx = 1 : numel(signal_names) %[output:group:95ed9601]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:8528d569] %[output:7b39bffc] %[output:99b53256] %[output:27b076f7] %[output:7e03e9ef] %[output:63048914] %[output:80681035]
  fig.Position(4) = 200;  % height
end %[output:group:95ed9601]
